BAK = '.bak-calc2-responsiva'
sha = lambda t: hashlib.sha256(t.encode('utf-8')).hexdigest()
def ler(p):
    raw = open(p, 'rb').read(); crlf = b'\r\n' in raw
    return raw, raw.decode('utf-8').replace('\r\n', '\n'), crlf
def main():
    a = [x for x in sys.argv[1:] if not x.startswith('--')]; raiz = os.path.abspath(a[0] if a else '.'); seco = '--dry-run' in sys.argv; desfazer = '--desfazer' in sys.argv; forcar = '--forcar' in sys.argv
    if not os.path.isdir(os.path.join(raiz, 'app')): print('Rode na RAIZ do projeto (a pasta que tem "app").'); return 2
    if desfazer:
        feitos = 0
        for rel, (hb, hn, _) in ARQUIVOS.items():
            p = os.path.join(raiz, *rel.split('/')); b = p + BAK
            if not os.path.exists(b): print('  (sem cópia de segurança) ' + rel); continue
            if not seco: shutil.copyfile(b, p); os.remove(b)
            feitos += 1; print(('  voltaria ' if seco else '  voltou ') + rel)
        print(('Nada foi gravado (--dry-run).' if seco else f'Desfeito: {feitos} arquivo(s).')); return 0
    plano = []; recusa = []
    for rel, (hb, hn, b64) in ARQUIVOS.items():
        p = os.path.join(raiz, *rel.split('/'))
        if not os.path.exists(p): recusa.append(rel + ' (não existe nesta pasta)'); continue
        raw, txt, crlf = ler(p); h = sha(txt)
        if h == hn: plano.append((rel, p, 'ja', crlf, b64)); continue
        if h == hb or forcar: plano.append((rel, p, 'trocar', crlf, b64)); continue
        recusa.append(rel + ' (foi editado depois da versão que me enviou)')
    if recusa:
        print('RECUSADO — nada foi alterado. Estes arquivos não são a versão esperada:'); [print('  - ' + r) for r in recusa]
        print('Me envie a versão atual deles (ou rode com --forcar se tiver certeza de que pode sobrescrever).'); return 1
    if all(x[2] == 'ja' for x in plano): print('Já aplicado. Nada foi alterado.'); return 0
    for rel, p, est, crlf, b64 in plano:
        if est == 'ja': print('  = já está novo ' + rel); continue
        if seco: print('  trocaria ' + rel + (' (mantém CRLF)' if crlf else '')); continue
        if not os.path.exists(p + BAK): shutil.copyfile(p, p + BAK)
        novo = base64.b64decode(b64).decode('utf-8')
        if crlf: novo = novo.replace('\n', '\r\n')
        open(p, 'wb').write(novo.encode('utf-8')); print('  ok ' + rel)
    print('Nada foi gravado (--dry-run).' if seco else 'Pronto. Rode o projeto, abra a Calculadora 2 e teste no celular. (Voltar atrás: --desfazer)'); return 0
sys.exit(main())
